mapper.select:
select

from profile_meta_label as t1
where label_id = #{labelId,jdbcType=VARCHAR}

select

from profile_meta_label as t1
where label_name = #{labelName,jdbcType=VARCHAR}

select

  ,
from profile_meta_label as t1
left outer join profile_meta_entity_identifier as t2
on t1.entity_identifier_id = t2.entity_identifier_id
left outer join profile_meta_entity as t3
on t2.entity_id = t3.entity_id
where 1 = 1

  AND t1.is_valid = #{isValid,jdbcType=INTEGER}


  AND t1.label_id = #{labelId,jdbcType=VARCHAR}


  AND t1.label_name = #{labelName,jdbcType=VARCHAR}


  AND t1.label_status = #{labelStatus,jdbcType=INTEGER}


  AND t1.label_type = #{labelType,jdbcType=VARCHAR}


  AND t1.label_category_id = #{labelCategoryId,jdbcType=VARCHAR}


  AND t1.label_data_type = #{labelDataType,jdbcType=INTEGER}


  AND t1.label_dist_type = #{labelDistType,jdbcType=INTEGER}


  AND t1.label_organize_type = #{labelOrganizeType,jdbcType=INTEGER}


  AND t1.label_produce_type = #{labelProduceType,jdbcType=INTEGER}


  AND t1.label_time_type = #{labelTimeType,jdbcType=INTEGER}


  AND t1.entity_identifier_id = #{entityIdentifierId,jdbcType=VARCHAR}


  AND t1.source_type = #{sourceType,jdbcType=INTEGER}


  AND t1.is_office = #{isOffice,jdbcType=INTEGER}


  AND t1.owner = #{owner,jdbcType=VARCHAR}


  AND t1.creator = #{creator,jdbcType=VARCHAR}


  AND t1.modifier = #{modifier,jdbcType=VARCHAR}


  AND t1.gmt_create = #{gmtCreate,jdbcType=TIMESTAMP}


  AND t1.gmt_modified = #{gmtModified,jdbcType=TIMESTAMP}
